-- Document the official Rosstat municipal migration series without importing
-- any numeric observations or changing source verification status.
update public.data_sources
set description = 'Официальная База данных показателей муниципальных образований Росстата. Перечень БД ПМО 2025 подтверждает годовые муниципальные показатели миграции: число прибывших (8112021), число выбывших (8112022) и миграционный прирост (8112023), доступные для всех типов муниципальных образований.',
    notes = 'Показатели миграции и их коды подтверждены в официальном перечне БД ПМО 2025: https://55.rosstat.gov.ru/storage/mediabank/pmo-2025.pdf . Публикация по графику Росстата — первая декада июля. Значения миграции пока не импортированы в municipality_indicators; требуется выгрузить таблицу отдельно по сопоставимым типам муниципальных образований и годам. Перед импортом проверить границы/названия муниципалитетов каждого года.'
where id = 'rosstat_municipal';
